-- =====================================================
-- 완료 메시지
-- =====================================================
SELECT '=== Seed Data Summary ===' AS message;
SELECT COUNT(*) AS users_count FROM users;
SELECT COUNT(*) AS clubs_count FROM clubs;
SELECT COUNT(*) AS members_count FROM members;
SELECT COUNT(*) AS squads_count FROM squads;
SELECT COUNT(*) AS squad_players_count FROM squad_players;
SELECT COUNT(*) AS lineups_count FROM lineups;
SELECT COUNT(*) AS lineup_slots_count FROM lineup_slots;
SELECT COUNT(*) AS chat_rooms_count FROM chat_rooms;
SELECT COUNT(*) AS chatters_count FROM chatters;
SELECT COUNT(*) AS chats_count FROM chats;
SELECT COUNT(*) AS schedules_count FROM schedules;
SELECT COUNT(*) AS attendances_count FROM attendances;

SELECT '=== Club Members ===' AS message;
SELECT c.name AS club_name, COUNT(m.id) AS member_count
FROM clubs c
LEFT JOIN members m ON c.id = m.club_id
GROUP BY c.id, c.name;

SELECT '=== Squad Players ===' AS message;
SELECT c.name AS club_name, COUNT(sp.id) AS player_count
FROM clubs c
LEFT JOIN squads sq ON c.id = sq.club_id
LEFT JOIN squad_players sp ON sq.id = sp.squad_id
GROUP BY c.id, c.name;

SELECT '=== Club Lineups ===' AS message;
SELECT c.name AS club_name, COUNT(l.id) AS lineup_count,
       SUM(CASE WHEN ls.id IS NOT NULL THEN 1 ELSE 0 END) AS total_slots
FROM clubs c
LEFT JOIN lineups l ON c.id = l.club_id
LEFT JOIN lineup_slots ls ON l.id = ls.lineup_id
GROUP BY c.id, c.name;

SELECT '=== Club Schedules ===' AS message;
SELECT c.name AS club_name, COUNT(s.id) AS schedule_count,
       SUM(CASE WHEN s.status = 'SCHEDULED' THEN 1 ELSE 0 END) AS upcoming,
       SUM(CASE WHEN s.status = 'COMPLETED' THEN 1 ELSE 0 END) AS completed
FROM clubs c
LEFT JOIN schedules s ON c.id = s.club_id
GROUP BY c.id, c.name;
